package com.haolin.vontlocal;
import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;

final class FocusStore {
    static final String FILE="focus-session-v1.json";static final FocusPolicy.Gate gate=new FocusPolicy.Gate();
    static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("focus-settings-v1",0);}
    static FocusPolicy.Settings settings(Context c){android.content.SharedPreferences p=prefs(c);return new FocusPolicy.Settings(p.getInt("workMinutes",50),p.getInt("restMinutes",5),p.getInt("restBrightness",30),p.getInt("restTemperature",3500));}
    static void saveSettings(Context c,FocusPolicy.Settings s){if(!prefs(c).edit().putInt("workMinutes",s.workMinutes).putInt("restMinutes",s.restMinutes).putInt("restBrightness",s.restBrightness).putInt("restTemperature",s.restTemperature).commit())throw new IllegalStateException("专注参数未保存");LinkWidget.updateAll(c);}
    static boolean running(){return gate.current!=null&&gate.valid(gate.current);}
    static boolean valid(String id){FocusPolicy.Session s=gate.current;return gate.valid(s)&&s.id.equals(id);}
    static void write(Context c,JSONObject data){try{ScreenbarClient.atomic(new File(c.getFilesDir(),FILE),data.toString(2).getBytes(StandardCharsets.UTF_8));}catch(Exception e){android.util.Log.e("QiguangFocus","Focus state persistence failed");}}
    static synchronized JSONObject state(Context c){JSONObject value;try{value=new JSONObject(new String(ScreenbarClient.readBytes(new File(c.getFilesDir(),FILE)),StandardCharsets.UTF_8));}catch(Exception e){return new JSONObject();}
        if(value.optBoolean("active")&&!valid(value.optString("sessionId"))){DeviceStore.put(value,"active",false);DeviceStore.put(value,"phase","interrupted");DeviceStore.put(value,"message","后台运行已中断，请确认后重新开始");write(c,value);}return value;}
    static synchronized void publish(Context c,FocusPolicy.Session s,String message){if(!gate.valid(s))return;JSONObject j=new JSONObject();DeviceStore.put(j,"sessionId",s.id);DeviceStore.put(j,"active",true);DeviceStore.put(j,"phase",s.phase);DeviceStore.put(j,"workMinutes",s.settings.workMinutes);DeviceStore.put(j,"restMinutes",s.settings.restMinutes);DeviceStore.put(j,"restBrightness",s.settings.restBrightness);DeviceStore.put(j,"restTemperature",s.settings.restTemperature);DeviceStore.put(j,"officeBrightness",s.officeBrightness);DeviceStore.put(j,"officeTemperature",s.officeTemperature);DeviceStore.put(j,"nextAtEpochMs",s.nextWall);DeviceStore.put(j,"message",message);DeviceStore.put(j,"updatedAtEpochMs",System.currentTimeMillis());write(c,j);LinkWidget.updateAll(c);}
    static synchronized FocusPolicy.Session end(Context c,String reason,String phase){FocusPolicy.Session s=gate.end();JSONObject j=state(c);DeviceStore.put(j,"active",false);DeviceStore.put(j,"phase",phase);DeviceStore.put(j,"message",reason);DeviceStore.put(j,"updatedAtEpochMs",System.currentTimeMillis());write(c,j);LinkWidget.updateAll(c);return s;}
    static String title(Context c){JSONObject s=state(c);if(!s.optBoolean("active"))return "提醒休息";String p=s.optString("phase");return p.equals("working")?"工作中":p.equals("resting")?"休息中":p.equals("preparing")?"准备办公中":"正在提醒";}
    static String detail(Context c){JSONObject s=state(c);if(s.optBoolean("active")){String p=s.optString("phase");if("working".equals(p)||"resting".equals(p)){if(s.optLong("nextAtEpochMs")<=System.currentTimeMillis())return "正在核对阶段 · 点此查看";return "预计 "+new java.text.SimpleDateFormat("HH:mm",java.util.Locale.CHINA).format(new java.util.Date(s.optLong("nextAtEpochMs")))+("working".equals(p)?" 休息":" 复工");}return "确认灯光后开始计时";}if("failed".equals(s.optString("phase"))||"interrupted".equals(s.optString("phase")))return s.optString("message","请确认后重新开始");FocusPolicy.Settings p=settings(c);return "工作 "+p.workMinutes+" 分钟 · 休息 "+p.restMinutes+" 分钟";}
}
